// Read-through wrapper in C#
public class ReadThroughCache<T>
{
    private readonly IDatabase _redis;
    private readonly AppDbContext _db;
    private readonly string _prefix;

    public ReadThroughCache(IConnectionMultiplexer redis, AppDbContext db, string prefix)
    {
        _redis = redis.GetDatabase();
        _db = db;
        _prefix = prefix;
    }

    public async Task<T?> GetAsync(string key, Func<AppDbContext, Task<T?>> dbLoader)
    {
        var cached = await _redis.StringGetAsync($"{_prefix}:{key}");
        if (cached.HasValue)
            return JsonSerializer.Deserialize<T>(cached!);

        var value = await dbLoader(_db);
        if (value is not null)
        {
            var json = JsonSerializer.Serialize(value);
            await _redis.StringSetAsync($"{_prefix}:{key}", json, TimeSpan.FromMinutes(10));
        }
        return value;
    }
}

// Usage
var orderCache = new ReadThroughCache<Order>(redis, db, "order");
var order = await orderCache.GetAsync("1001", ctx => ctx.Orders.FindAsync(1001));

// Read-through wrapper in Node.js
const Redis = require('ioredis');
const redis = new Redis(process.env.REDIS_URL);

class ReadThroughCache {
  constructor(prefix, ttlSeconds) {
    this.prefix = prefix;
    this.ttl = ttlSeconds;
  }

  async get(key, dbLoader) {
    const cacheKey = `${this.prefix}:${key}`;
    const cached = await redis.get(cacheKey);
    if (cached) return JSON.parse(cached);

    const value = await dbLoader();
    if (value) {
      await redis.setex(cacheKey, this.ttl, JSON.stringify(value));
    }
    return value;
  }
}

const orderCache = new ReadThroughCache('order', 600);

async function getOrder(id) {
  return orderCache.get(id, () => db('orders').where('id', id).first());
}
